const e="deped-bohol-culture-arts",u=2018,t="Read all 4 pages of the guideline. It prints no fee, no venue, no event dates (only the portfolio deadline), no prizes or ranks, no ages, and no contact details except the portfolio recipient. Culture Mapping sub-marks are written in the judging rules because the template carries only the two 50 percent parts.",n={Title:"Rules & Criteria",Subtitle:"Division of Bohol Culture and Arts Competitions, School Year {{SchoolYear}}. Read the rules before you register.",NoticeTitle:"Please Read Before Registering",Notice:"Theme: {{Theme}}. Events are competed from District level up to Division level. The Culture Mapping portfolio is due on {{PortfolioDeadline}}.",Notes:["The decision of the Board of Judges is final and cannot be changed."],Sections:[{Key:"general",Title:"General Guidelines",Items:["The theme of the culture and arts competition this year is {{Theme}}.","All the Culture and Arts events are competed starting from the District up to the Division level.","The winning participants represent the Division of Bohol for possible higher-level competitions and programs related to Culture and Arts.","The decision of the Board of Judges is final and cannot be changed."]},{Key:"eligibility",Title:"Eligibility",Items:["Winning participants in all levels in the previous school years can still take part in this school year's competition and in the school years after.","Flute and Ukulele Ensemble is open to elementary school learners currently enrolled for school year {{SchoolYear}}.","Guitar Ensemble and Sayawit are open to secondary school learners currently enrolled for school year {{SchoolYear}}.","Kuradang Dance Contest and Culture Mapping are open to all elementary or secondary school teachers teaching in the Division of Bohol."]},{Key:"levels",Title:"Levels",Items:["Each event is competed from District level to Division level.","The winners represent the Division of Bohol at higher levels."]},{Key:"teams",Title:"Team Sizes",Items:["Flute and Ukulele Ensemble and Guitar Ensemble: 15 to 20 performers and one teacher-coach, who is also the conductor.","Sayawit: at least 5 and at most 7 performers (male, female or a mix), not counting the instrumentalists.","Kuradang Dance Contest: at least 4 and at most 5 pairs (male and female partners only).","Culture Mapping: five members and one coach from the same municipality. There is only one team in each municipality."]},{Key:"dates",Title:"Dates",Items:["The Culture Mapping portfolio must be submitted on or before {{PortfolioDeadline}}."]},{Key:"registration",Title:"Submissions",Items:["Culture Mapping portfolio: submit it on or before {{PortfolioDeadline}} to {{PortfolioOffice}}.","The portfolio must have the received mark from the record section, to show the exact date of submission."]}],Documents:[{Title:"Guidelines for Culture and Arts Competitions SY 2018-2019 (PDF)",Url:"https://depedbohol.org/v2/wp-content/uploads/2018/07/Guidelines-for-Culture.pdf"}]},o=[],a=[{AgeGroup:"Elementary Learners",Source:"Guidelines for Culture and Arts Competitions SY 2018-2019 p.1 (A. Flute and Ukulele Ensemble)",Sections:{About:null,TimeAndFormat:null,Rules:["Learners who are currently enrolled in elementary school for school year {{SchoolYear}}.","The rules print no age. The template ages are placeholders."],Allowed:null,NotAllowed:null,Judging:null,Points:null,Notes:null},Markdown:`## Rules
- Learners who are currently enrolled in elementary school for school year {{SchoolYear}}.
- The rules print no age. The template ages are placeholders.`},{AgeGroup:"Secondary Learners",Source:"Guidelines for Culture and Arts Competitions SY 2018-2019 p.2 (B. Guitar Ensemble, C. Sayawit)",Sections:{About:null,TimeAndFormat:null,Rules:["Learners who are currently enrolled in secondary school for school year {{SchoolYear}}.","The rules print no age. The template ages are placeholders."],Allowed:null,NotAllowed:null,Judging:null,Points:null,Notes:null},Markdown:`## Rules
- Learners who are currently enrolled in secondary school for school year {{SchoolYear}}.
- The rules print no age. The template ages are placeholders.`},{AgeGroup:"Teachers",Source:"Guidelines for Culture and Arts Competitions SY 2018-2019 p.3 (D. Kuradang, E. Culture Mapping)",Sections:{About:null,TimeAndFormat:null,Rules:["Elementary or secondary school teachers teaching in the Division of Bohol.","The rules print no age. The template ages are placeholders."],Allowed:null,NotAllowed:null,Judging:null,Points:null,Notes:null},Markdown:`## Rules
- Elementary or secondary school teachers teaching in the Division of Bohol.
- The rules print no age. The template ages are placeholders.`}],i=JSON.parse(`[{"Title":"Flute and Ukulele Ensemble","Source":"Guidelines for Culture and Arts Competitions SY 2018-2019 p.1 (A)","Sections":{"About":null,"TimeAndFormat":["Performance time is 5 to 7 minutes including entrance and exit.","Time starts when the performers enter the stage and stops after the last person leaves the stage.","Five points are deducted from the total score of the performers for every excess minute."],"Rules":["15 to 20 performers and one teacher-coach, who is also the conductor during the presentation.","The coach decides the number of flute or ukulele players, as long as the total is not below or above the required number of performers.","The pieces must include one Visayan folk song, one Makabayan song and one song mastered by the group.","Performers wear Filipiniana costume."],"Allowed":["Only flute and ukulele."],"NotAllowed":["Other instruments.","Other persons on stage except the performers and the conductor, during the whole presentation."],"Judging":["Repertoire 15%: the choice of songs played by the group after the 3 required pieces.","Musicality 40%: sensitivity to, knowledge of or talent for music, including clear and well-balanced pitch, rhythm, harmony and synchronization of instruments for a homogeneous sound quality.","Mastery 35%: the whole performance, including great skills and technique, creativity and presence of mind.","Deportment 10%: the appeal or bearing, attitude of the participants and how they present themselves on stage.","Total 100%."],"Points":null,"Notes":null},"Markdown":"## Time and format\\n- Performance time is 5 to 7 minutes including entrance and exit.\\n- Time starts when the performers enter the stage and stops after the last person leaves the stage.\\n- Five points are deducted from the total score of the performers for every excess minute.\\n\\n## Rules\\n- 15 to 20 performers and one teacher-coach, who is also the conductor during the presentation.\\n- The coach decides the number of flute or ukulele players, as long as the total is not below or above the required number of performers.\\n- The pieces must include one Visayan folk song, one Makabayan song and one song mastered by the group.\\n- Performers wear Filipiniana costume.\\n\\n## Allowed\\n- Only flute and ukulele.\\n\\n## Not allowed\\n- Other instruments.\\n- Other persons on stage except the performers and the conductor, during the whole presentation.\\n\\n## Judging\\n- Repertoire 15%: the choice of songs played by the group after the 3 required pieces.\\n- Musicality 40%: sensitivity to, knowledge of or talent for music, including clear and well-balanced pitch, rhythm, harmony and synchronization of instruments for a homogeneous sound quality.\\n- Mastery 35%: the whole performance, including great skills and technique, creativity and presence of mind.\\n- Deportment 10%: the appeal or bearing, attitude of the participants and how they present themselves on stage.\\n- Total 100%."},{"Title":"Guitar Ensemble","Source":"Guidelines for Culture and Arts Competitions SY 2018-2019 p.2 (B)","Sections":{"About":null,"TimeAndFormat":["Performance time is 5 to 7 minutes including entrance and exit.","Time starts when the performers enter the stage and stops after the last person leaves the stage.","Five points are deducted from the total score of the performers for every excess minute."],"Rules":["15 to 20 performers and one teacher-coach, who is also the conductor during the presentation.","The pieces must include one Visayan folk song, one Makabayan song and one song mastered by the group.","Performers wear Filipiniana costume."],"Allowed":["Players use only their own acoustic guitar, with or without pick-up sound connectors or cords."],"NotAllowed":["Other persons on stage except the performers and the conductor, during the whole presentation."],"Judging":["Repertoire 15%: the choice of songs played by the group after the 3 required pieces.","Musicality 40%: sensitivity to, knowledge of or talent for music, including clear and well-balanced pitch, rhythm, harmony and synchronization of instruments for a homogeneous sound quality.","Mastery 35%: the whole performance, including great skills and technique, creativity and presence of mind.","Deportment 10%: the appeal or bearing, attitude of the participants and how they present themselves on stage.","Total 100%."],"Points":null,"Notes":null},"Markdown":"## Time and format\\n- Performance time is 5 to 7 minutes including entrance and exit.\\n- Time starts when the performers enter the stage and stops after the last person leaves the stage.\\n- Five points are deducted from the total score of the performers for every excess minute.\\n\\n## Rules\\n- 15 to 20 performers and one teacher-coach, who is also the conductor during the presentation.\\n- The pieces must include one Visayan folk song, one Makabayan song and one song mastered by the group.\\n- Performers wear Filipiniana costume.\\n\\n## Allowed\\n- Players use only their own acoustic guitar, with or without pick-up sound connectors or cords.\\n\\n## Not allowed\\n- Other persons on stage except the performers and the conductor, during the whole presentation.\\n\\n## Judging\\n- Repertoire 15%: the choice of songs played by the group after the 3 required pieces.\\n- Musicality 40%: sensitivity to, knowledge of or talent for music, including clear and well-balanced pitch, rhythm, harmony and synchronization of instruments for a homogeneous sound quality.\\n- Mastery 35%: the whole performance, including great skills and technique, creativity and presence of mind.\\n- Deportment 10%: the appeal or bearing, attitude of the participants and how they present themselves on stage.\\n- Total 100%."},{"Title":"Sayawit","Source":"Guidelines for Culture and Arts Competitions SY 2018-2019 p.2-3 (C)","Sections":{"About":null,"TimeAndFormat":["The presentation lasts at most 6 minutes and at least 3 minutes, including entrance and exit.","Time starts when the performers enter the stage and stops after the last person leaves the stage.","Five points are deducted from the total score of the performers for every excess minute."],"Rules":["At least 5 and at most 7 performers (male, female or a mix), not counting the instrumentalists.","The songs must only be Visayan folk songs and must be sung continuously.","The performance must be song and dance in line with the theme. Performers must sing and dance at the same time.","The accompaniment must be live. Any instruments that suit the whole concept of the presentation can be used."],"Allowed":null,"NotAllowed":["Props."],"Judging":["Theme Relevance 15%: the choice of songs, costumes and the overall concept.","Performance 35%: staging, spacing, formations, execution, showmanship, projection, entertainment value and crowd appeal.","Musicality 25%: sensitivity to, knowledge of or talent for music, including clear and well-balanced pitch, rhythm, harmony and voice quality.","Choreography and Originality 25%: dance arrangements and concept with unique, original and creative moves.","Total 100%."],"Points":null,"Notes":null},"Markdown":"## Time and format\\n- The presentation lasts at most 6 minutes and at least 3 minutes, including entrance and exit.\\n- Time starts when the performers enter the stage and stops after the last person leaves the stage.\\n- Five points are deducted from the total score of the performers for every excess minute.\\n\\n## Rules\\n- At least 5 and at most 7 performers (male, female or a mix), not counting the instrumentalists.\\n- The songs must only be Visayan folk songs and must be sung continuously.\\n- The performance must be song and dance in line with the theme. Performers must sing and dance at the same time.\\n- The accompaniment must be live. Any instruments that suit the whole concept of the presentation can be used.\\n\\n## Not allowed\\n- Props.\\n\\n## Judging\\n- Theme Relevance 15%: the choice of songs, costumes and the overall concept.\\n- Performance 35%: staging, spacing, formations, execution, showmanship, projection, entertainment value and crowd appeal.\\n- Musicality 25%: sensitivity to, knowledge of or talent for music, including clear and well-balanced pitch, rhythm, harmony and voice quality.\\n- Choreography and Originality 25%: dance arrangements and concept with unique, original and creative moves.\\n- Total 100%."},{"Title":"Kuradang Dance Contest","Source":"Guidelines for Culture and Arts Competitions SY 2018-2019 p.3 (D)","Sections":{"About":null,"TimeAndFormat":null,"Rules":["At least 4 and at most 5 pairs (male and female partners only).","The Kuradang basic dance steps must be followed strictly, with variations from other existing local kuradang steps or movements. Steps: {{KuradangSteps}}.","The main shape of the costumes is based on the local traditional Boholano baro at saya. Designs can include materials and accessories that show the design traditions and heritage assets of the community.","The official music is {{KuradangMusic}}."],"Allowed":null,"NotAllowed":["Props."],"Judging":["Performance 40%: staging, spacing, formations, execution, showmanship, projection, entertainment value and crowd appeal.","Choreography and Originality 35%: dance arrangements and concept with unique, original and creative moves.","Utilization of Heritage Tradition 15%: correct use of local dance movements and an appropriate costume with designs and materials showing the design traditions and heritage assets of the community.","Over-all Impact 10%.","Total 100%."],"Points":null,"Notes":null},"Markdown":"## Rules\\n- At least 4 and at most 5 pairs (male and female partners only).\\n- The Kuradang basic dance steps must be followed strictly, with variations from other existing local kuradang steps or movements. Steps: {{KuradangSteps}}.\\n- The main shape of the costumes is based on the local traditional Boholano baro at saya. Designs can include materials and accessories that show the design traditions and heritage assets of the community.\\n- The official music is {{KuradangMusic}}.\\n\\n## Not allowed\\n- Props.\\n\\n## Judging\\n- Performance 40%: staging, spacing, formations, execution, showmanship, projection, entertainment value and crowd appeal.\\n- Choreography and Originality 35%: dance arrangements and concept with unique, original and creative moves.\\n- Utilization of Heritage Tradition 15%: correct use of local dance movements and an appropriate costume with designs and materials showing the design traditions and heritage assets of the community.\\n- Over-all Impact 10%.\\n- Total 100%."},{"Title":"Culture Mapping","Source":"Guidelines for Culture and Arts Competitions SY 2018-2019 p.3-4 (E)","Sections":{"About":["Cultural mapping is a systematic way of identifying, recording, classifying and analyzing a community's cultural resources or cultural assets that trace the historical, economic, social and geographical importance of a site. Cultural heritage assets are generally classified as tangible and intangible."],"TimeAndFormat":null,"Rules":["One team of five members and one coach, all from the same municipality. Only one team in each municipality.","The team must present both tangible and intangible cultural heritage resources or assets.","The competition has two parts: Part A Portfolio and Part B Cultural Exhibit.","Part A Portfolio: the compilation and documentation of the identified tangible and intangible cultural heritage assets of the community. Submit it on or before {{PortfolioDeadline}} to {{PortfolioOffice}}, with the received mark from the record section.","Part B Cultural Exhibit: the creative display of the highlights of the cultural mapping outputs. It must be based only on the contents of the submitted portfolio.","At the exhibit, the safety and security of the heritage items brought are the responsibility of the participating teams.","Only the members of the team may be at the exhibit site during judging.","No tents are needed unless the exhibit is in an outdoor venue.","The participating teams do the after care.","Only items found in the portfolio are shown at the exhibit. Items shown that are not in the portfolio are not counted."],"Allowed":null,"NotAllowed":null,"Judging":["Part A Portfolio is 50%. Content 50% of the portfolio: correctness of data (heritage item) 15, authenticity (from reliable sources) 15, completeness of data 10, quantity 10.","Part A Process 20% of the portfolio: evidence, by pictures or videos, that the team went through the mapping process.","Part A Output 30% of the portfolio: presentation (artistry and creativity) 10, organization 15, punctuality of submission 5.","Part B Cultural Exhibit is 50%. Presentation 40% of the exhibit: artistry and creativity, responsible use of indigenous materials.","Part B Organization 30% of the exhibit: relevance to the concept, orderliness of presentation, completeness of data.","Part B Interview 30% of the exhibit: appeal of the team, ability to answer questions, wit and confidence.","Total 100%."],"Points":null,"Notes":null},"Markdown":"## About this competition\\n- Cultural mapping is a systematic way of identifying, recording, classifying and analyzing a community's cultural resources or cultural assets that trace the historical, economic, social and geographical importance of a site. Cultural heritage assets are generally classified as tangible and intangible.\\n\\n## Rules\\n- One team of five members and one coach, all from the same municipality. Only one team in each municipality.\\n- The team must present both tangible and intangible cultural heritage resources or assets.\\n- The competition has two parts: Part A Portfolio and Part B Cultural Exhibit.\\n- Part A Portfolio: the compilation and documentation of the identified tangible and intangible cultural heritage assets of the community. Submit it on or before {{PortfolioDeadline}} to {{PortfolioOffice}}, with the received mark from the record section.\\n- Part B Cultural Exhibit: the creative display of the highlights of the cultural mapping outputs. It must be based only on the contents of the submitted portfolio.\\n- At the exhibit, the safety and security of the heritage items brought are the responsibility of the participating teams.\\n- Only the members of the team may be at the exhibit site during judging.\\n- No tents are needed unless the exhibit is in an outdoor venue.\\n- The participating teams do the after care.\\n- Only items found in the portfolio are shown at the exhibit. Items shown that are not in the portfolio are not counted.\\n\\n## Judging\\n- Part A Portfolio is 50%. Content 50% of the portfolio: correctness of data (heritage item) 15, authenticity (from reliable sources) 15, completeness of data 10, quantity 10.\\n- Part A Process 20% of the portfolio: evidence, by pictures or videos, that the team went through the mapping process.\\n- Part A Output 30% of the portfolio: presentation (artistry and creativity) 10, organization 15, punctuality of submission 5.\\n- Part B Cultural Exhibit is 50%. Presentation 40% of the exhibit: artistry and creativity, responsible use of indigenous materials.\\n- Part B Organization 30% of the exhibit: relevance to the concept, orderliness of presentation, completeness of data.\\n- Part B Interview 30% of the exhibit: appeal of the team, ability to answer questions, wit and confidence.\\n- Total 100%."}]`),r=[],s=[{Key:"SchoolYear",Kind:"text",Label:"School year of the competitions",Value:"2018-2019",Source:"Guidelines for Culture and Arts Competitions SY 2018-2019 p.1"},{Key:"Theme",Kind:"text",Label:"Theme of the year",Value:"Ipasigarbo ang Kulturang Bol-anon",Source:"Guidelines for Culture and Arts Competitions SY 2018-2019 p.1 General Guidelines 1"},{Key:"PortfolioDeadline",Kind:"date",Label:"Last date to submit the Culture Mapping portfolio",Value:"2018-11-09",Source:"Guidelines for Culture and Arts Competitions SY 2018-2019 p.4 (Culture Mapping 5A)"},{Key:"PortfolioOffice",Kind:"contact",Label:"Where the Culture Mapping portfolio is submitted",Value:{Name:"Mr. Cirilo Calatrava",Role:"Division Office (portfolio must carry the received mark of the record section)",Phone:"",WhatsApp:"",Email:""},Source:"Guidelines for Culture and Arts Competitions SY 2018-2019 p.4 (Culture Mapping 5A)"},{Key:"KuradangMusic",Kind:"text",Label:"Official music for the Kuradang Dance Contest",Value:"Sandugo Kuradang Streetdancing 2018 music",Source:"Guidelines for Culture and Arts Competitions SY 2018-2019 p.3 (Kuradang 5)"},{Key:"KuradangSteps",Kind:"text",Label:"Basic steps to follow in the Kuradang Dance Contest",Value:"The Kuradang basic dance steps promoted by the Provincial Government through the Center for Culture and the Arts Development, used in the Kuradang streetdancing showdown during Sandugo Festival 2018",Source:"Guidelines for Culture and Arts Competitions SY 2018-2019 p.3 (Kuradang 3)"}],l=[{Claim:"Division of Bohol (DepEd) Guidelines for Culture and Arts Competitions, School Year 2018-2019: general guidelines and the specific guidelines for five events (image-only PDF, all 4 pages read).",SourceType:"Primary - the event's own rules document",Source:"Guidelines for Culture and Arts Competitions SY 2018-2019",Url:"https://depedbohol.org/v2/wp-content/uploads/2018/07/Guidelines-for-Culture.pdf"}],h={TemplateKey:e,Year:2018,Note:t,Page:n,ParticipantTypes:o,AgeGroups:a,Competitions:i,CompetitionAgeGroups:r,Variables:s,Evidence:l};export{a as AgeGroups,r as CompetitionAgeGroups,i as Competitions,l as Evidence,t as Note,n as Page,o as ParticipantTypes,e as TemplateKey,s as Variables,u as Year,h as default};
